head.script:
scwin.fn01 = function(rowObj,rowIdx){
    //console.log(rowObj);
    //console.log(rowIdx);
    return rowObj.col1;
};

scwin.fn02 = function(rowObj,rowIdx){
    //console.log(rowObj);
    //console.log(rowIdx);
    return rowObj[this.getColumnIndex("col1")];
};


scwin.onpageload = function() {
};

scwin.textbox1_onclick = function (e) {
    var data = [
            {
                "col1": "삼립빵",
                "col2": 1,
                "col3": 2
            },
            {
                "col1": "마늘빵",
                "col2": 3,
                "col3": 4
            },
            {
                "col1": "모카빵",
                "col2": 5,
                "col3": 6
            }
        ];


dataList3.setJSON(data);

};


scwin.textbox2_onclick = function (e) {
var data = ['삼립빵', 1, 2, '', '', '', '마늘빵', 3, 4, '', '', '', '모카빵', 5, 6, '', '', ''];
dataList3.setData(data);
};

scwin.textbox3_onclick = function (e) {
var dataArr = {
    "columnInfo": ["col1", "col2", "col3"], 
    "data":[
        '삼립빵', 1, 2,
        '마늘빵', 3, 4,
        '모카빵', 5, 6
    ]
};
dataList3.setArray(dataArr);
};

scwin.textbox4_onclick = function (e) {
// XML 문자열 생성
var tmpXMLStr = "";
tmpXMLStr += "<list id=\"dataList3\">";
tmpXMLStr += "<map index=\"0\">";
tmpXMLStr += "<col1>삼립빵</col1>";
tmpXMLStr += "<col2>1</col2>";
tmpXMLStr += "<col3>2</col3>";
tmpXMLStr += "</map>";
tmpXMLStr += "<map index=\"1\">";
tmpXMLStr += "<col1>마늘빵</col1>";
tmpXMLStr += "<col2>3</col2>";
tmpXMLStr += "<col3>4</col3>";
tmpXMLStr += "</map>";
tmpXMLStr += "<map index=\"2\">";
tmpXMLStr += "<col1>모카빵</col1>";
tmpXMLStr += "<col2>5</col2>";
tmpXMLStr += "<col3>6</col3>";
tmpXMLStr += "</map>";
tmpXMLStr += "</list>";


// XML 데이터 생성
var tmpXML = WebSquare.xml.parse(tmpXMLStr);

// XML 형태의 2건의 리스트 데이터를 추가
dataList3.setXML(tmpXML);
};

scwin.textbox5_onclick = function (e) {
var tmpXMLStr ="";
tmpXMLStr += "<map>";
tmpXMLStr += "<col1>삼립빵</col1>";
tmpXMLStr += "<col2>1</col2>";
tmpXMLStr += "<col3>2</col3>";
tmpXMLStr += "</map>";

var xmlDoc = WebSquare.xml.parse(tmpXMLStr);

dataList3.setRowXML(0, xmlDoc);

};

scwin.textbox6_onclick = function (e) {
dataList3.setRowJSON(0, {"col1": "삼립빵","col2": 1,"col3": 2,"col4": '',"col5": '',"col6": ''});
};

scwin.textbox7_onclick = function (e) {
    dataList3.setCellData(0,"col1","삼립빵 수정");
};


	scwin.checkVal1 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_10_cell_0_0').innerText == '삼립빵';
	}	
	scwin.checkVal2 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_10_cell_0_3').innerText == '삼립빵';
	}	
	scwin.checkVal3 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_10_cell_0_6').innerText == '삼립빵';
	}	
	scwin.checkVal4 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_10_cell_0_0').innerText == '삼립빵 수정';
	}	
	scwin.checkVal5 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_10_cell_0_3').innerText == '삼립빵 수정';
	}	
	scwin.checkVal6 = function() {
		return WebSquare.wUnit.getDomById('wq_uuid_10_cell_0_6').innerText == '삼립빵';
	}		
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox1').click()");
		WebSquare.wUnit.addCommand("pause", "500");				
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal3()", "true");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('textbox7').click()");
		WebSquare.wUnit.addCommand("pause", "500");			
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal4()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal5()", "true");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal6()", "true");
		WebSquare.wUnit.addCommand("pause", "500");		

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
